function t(k){return (L[state.lang]||L.fr)[k]||L.fr[k]||k}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function activeProfile(){return state.profiles.find(p=>p.id===state.activeProfileId)||null}
function ageText(birth){if(!birth)return"";const b=new Date(birth+"T00:00:00"),n=new Date();let m=(n.getFullYear()-b.getFullYear())*12+n.getMonth()-b.getMonth();if(n.getDate()<b.getDate())m--;return m<24?m+" mois":Math.floor(m/12)+" "+(state.lang==="en"?"years":state.lang==="ar"?"سنة":state.lang==="es"?"años":"ans")}
function toast(msg){const el=document.getElementById("toast");el.textContent=msg;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),1700)}
function btn(label,fn,cls="primary"){return '<button class="btn '+cls+'" onclick="'+fn+'">'+label+'</button>'}
function header(title,sub){return '<div class="top"><button class="back" onclick="back()">‹ '+t("back")+'</button><span style="color:#efce8b">♡</span></div><div class="eyebrow">'+(sub||"NAËL")+'</div><h1 class="pageTitle">'+title+'</h1>'}
function nav(active){const x=[["⌂","home","home"],["✦","tracking","tracking"],["♡","health","health"],["☺","profile","profile"],["⚙","settings","settings"]];return '<nav class="bottom premiumNav">'+x.map(i=>'<button class="nav '+(active===i[2]?'active':'')+'" onclick="go(\''+i[2]+'\')"><span>'+i[0]+'</span><small>'+t(i[1])+'</small></button>').join("")+'<button class="fab" onclick="openQuickAdd()" aria-label="Ajouter">＋</button></nav>'}
function shell(body,active,home){return '<main class="screen">'+(home?'<div class="top"><div class="homeBrand">Naël</div><div><button class="back" onclick="openMod(\'settings\')">⚙️</button><button class="back" onclick="openMod(\'reminders\')">🔔</button></div></div>':'')+body+'</main>'+nav(active)}
function avatarHTML(p,cls="avatar"){return p&&p.photo?'<div class="'+cls+'"><img src="'+p.photo+'" alt=""></div>':'<div class="'+cls+'">'+esc((p&&p.avatar)||"👶")+'</div>'}
function todayEvents(type){const d=new Date().toDateString(),pid=state.activeProfileId;return state.events.filter(e=>e.profileId===pid&&new Date(e.ts).toDateString()===d&&(!type||e.type===type))}
function upcomingAppointments(){return state.appointments.filter(a=>a.profileId===state.activeProfileId&&new Date(a.date).getTime()>=Date.now()).sort((a,b)=>new Date(a.date)-new Date(b.date))}
function upcomingVaccines(){const now=new Date().toISOString().slice(0,10);return state.vaccines.filter(v=>v.profileId===state.activeProfileId&&v.status!=="done"&&(!v.date||v.date>=now)).sort((a,b)=>(a.date||"9999").localeCompare(b.date||"9999"))}
function dueReminders(){return state.reminders.filter(r=>r.profileId===state.activeProfileId&&!r.done&&new Date(r.when).getTime()<=Date.now())}

function eventLabel(e){if(e.type==="feeding")return t("feeding");if(e.type==="sleep")return t("sleep");if(e.type==="diapers")return t("diapers");if(e.type==="activities")return t("activities");if(e.type==="healthlog")return t("healthLog");if(e.type==="journal")return t("journal");if(e.type==="memories")return t("memories");return e.type}
function eventIcon(e){const m={feeding:"🍼",sleep:"🌙",diapers:"🧷",activities:"🧸",healthlog:"❤️",journal:"📖",memories:"📷"};return m[e.type]||"•"}
function todayTimeline(){const items=todayEvents().slice().sort((a,b)=>new Date(b.ts)-new Date(a.ts)).slice(0,7);if(!items.length)return '<div class="empty card">'+t("noHistory")+'</div>';return '<div class="timeline card">'+items.map(e=>'<div class="timelineRow"><span class="timelineIcon">'+eventIcon(e)+'</span><div class="timelineMain"><b>'+new Date(e.ts).toLocaleTimeString(state.lang,{hour:"2-digit",minute:"2-digit"})+' · '+eventLabel(e)+'</b><small>'+esc(e.note||"")+(e.ml?' · '+e.ml+' ml':'')+(e.durationMin?' · '+e.durationMin+' min':'')+'</small></div></div>').join("")+'</div>'}
function nextActionCard(){const ap=upcomingAppointments()[0],va=upcomingVaccines()[0],due=dueReminders();if(due.length)return '<div class="nextCard card urgent" onclick="openMod(\'reminders\')"><span class="nextIcon">🔔</span><div><small>'+t("due")+'</small><b>'+due.length+' · '+esc(due[0].title)+'</b></div><span class="right">›</span></div>';const items=[];if(ap)items.push({k:"appointments",icon:"📅",label:t("appointments"),text:ap.title,date:new Date(ap.date)});if(va&&va.date)items.push({k:"vaccines",icon:"💉",label:t("vaccines"),text:va.name,date:new Date(va.date+"T09:00:00")});state.reminders.filter(r=>r.profileId===state.activeProfileId&&!r.done&&new Date(r.when).getTime()>Date.now()).forEach(r=>items.push({k:"reminders",icon:"🔔",label:t("reminders"),text:r.title,date:new Date(r.when)}));items.sort((a,b)=>a.date-b.date);const x=items[0];if(!x)return "";return '<div class="nextCard card" onclick="openMod(\''+x.k+'\')"><span class="nextIcon">'+x.icon+'</span><div><small>'+x.label+'</small><b>'+esc(x.text)+'</b><em>'+x.date.toLocaleString(state.lang,{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})+'</em></div><span class="right">›</span></div>'}


function smartDailySummary(){const ev=todayEvents();if(!ev.length)return '<div class="notice">'+t("smartSummaryEmpty")+'</div>';const feeds=ev.filter(e=>e.type==="feeding"),sleeps=ev.filter(e=>e.type==="sleep"),diapers=ev.filter(e=>e.type==="diapers"),sleepMin=sleeps.reduce((n,e)=>n+(Number(e.durationMin)||0),0),ml=feeds.reduce((n,e)=>n+(Number(e.ml)||0),0);const parts=[];if(feeds.length)parts.push(feeds.length+" "+t("feeding").toLowerCase()+(ml?" · "+ml+" ml":""));if(sleeps.length)parts.push(Math.round(sleepMin/60*10)/10+" h "+t("sleep").toLowerCase());if(diapers.length)parts.push(diapers.length+" "+t("diapers").toLowerCase());return '<div class="smartSummary card"><div class="smartIcon">✨</div><div><small>'+t("smartSummary")+'</small><b>'+parts.join(" • ")+'</b><p>'+t("gift")+'</p></div></div>'}
function moduleGrid(){return '<div class="grid">'+Object.entries(mods).filter(([k])=>k!=="settings").map(([k,m])=>'<div class="module card" onclick="openMod(\''+k+'\')"><span class="mi">'+m[0]+'</span><span class="ml">'+t(m[1])+'</span></div>').join("")+'</div>'}
function quickAddHTML(){const p=activeProfile();const items=[["🍼","feeding","meal"],["🌙","sleep","sleep"],["🧷","diapers","diaper"],["📈","growth","growth"],["📅","appointments","appointments"],["🔔","reminders","reminders"],["⭐","milestones","milestones"],["💊","medications","medications"],["✅","checklists","checklists"],["📄","documents","documents"],["🧳","travel","travel"],["✨","ai","naelAI"]];return '<div class="quickOverlay" onclick="closeQuickAdd(event)"><div class="quickSheet" onclick="event.stopPropagation()"><div class="quickHandle"></div><div class="quickHead"><div><div class="eyebrow">NAËL QUICK ADD</div><h2>'+t("daily")+'</h2><p>'+t("dailyBody")+'</p></div><button class="quickClose" onclick="closeQuickAdd()">×</button></div><div class="quickGrid">'+items.map(i=>'<button class="quickAction" onclick="quickOpen(\''+i[1]+'\')"><span>'+i[0]+'</span><b>'+t(i[2])+'</b></button>').join("")+'</div>'+(p?'<div class="quickProfile">'+avatarHTML(p,"miniA")+'<div><b>'+esc(p.name)+'</b><small>'+esc(ageText(p.birth))+'</small></div></div>':'<div class="notice">'+t("createFirstBody")+'</div>')+'</div></div>'}
window.openQuickAdd=()=>{document.body.insertAdjacentHTML("beforeend",quickAddHTML());document.body.classList.add("noScroll")}
window.closeQuickAdd=e=>{if(e&&e.target!==e.currentTarget)return;document.querySelector(".quickOverlay")?.remove();document.body.classList.remove("noScroll")}
window.quickOpen=k=>{closeQuickAdd();if(!activeProfile()&&k!=="ai"){state.screen="profile";state.module=null;save();render();toast(t("createFirst"));return}openMod(k)}
function render(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==="ar"?"rtl":"ltr";if(state.module){renderModule();return}if(state.screen==="home")renderHome();else if(state.screen==="tracking")renderTracking();else if(state.screen==="health")renderHealth();else if(state.screen==="discover")renderDiscover();else renderProfile()}
function renderHome(){const p=activeProfile();if(!p){root.innerHTML=shell('<div class="eyebrow">'+t("welcome")+'</div><h1 class="pageTitle">'+t("createFirst")+'</h1><p class="subtitle">'+t("createFirstBody")+'</p>'+btn(t("createProfile"),"newProfile()"),"home",true);return}const ap=upcomingAppointments()[0],va=upcomingVaccines()[0];root.innerHTML=shell(profileSwitcher()+'<div class="eyebrow">'+t("today")+' ✨</div><h1 class="pageTitle">'+t("amazing")+'</h1><div class="hero card"><div class="eyebrow">'+t("today")+'</div><h2>'+t("gift")+', '+esc(p.name)+'</h2><p>'+esc(ageText(p.birth))+' • '+dueReminders().length+' '+t("reminders").toLowerCase()+'</p></div>'+smartDailySummary()+'<div class="profileStrip card" onclick="go(\'profile\')">'+avatarHTML(p)+'<div><b>'+esc(p.name)+'</b><small>'+esc(ageText(p.birth))+'</small></div><div class="chev">›</div></div><div class="stats"><div class="stat card"><b>'+todayEvents("feeding").length+'</b><small>'+t("meal")+'</small></div><div class="stat card"><b>'+todayEvents("sleep").length+'</b><small>'+t("sleep")+'</small></div><div class="stat card"><b>'+todayEvents("diapers").length+'</b><small>'+t("diapers")+'</small></div></div><div class="quickbar"><button class="quick card" onclick="openMod(\'feeding\')"><span>🍼</span><small>'+t("meal")+'</small></button><button class="quick card" onclick="openMod(\'sleep\')"><span>🌙</span><small>'+t("sleep")+'</small></button><button class="quick card" onclick="openMod(\'diapers\')"><span>🧷</span><small>'+t("diaper")+'</small></button></div><h2 class="sectionTitle">'+t("summary")+'</h2><div class="summary card"><div class="summaryRow"><span>'+t("nextAppt")+'</span><span>'+(ap?new Date(ap.date).toLocaleDateString():"—")+'</span></div><div class="summaryRow"><span>'+t("nextVax")+'</span><span>'+(va&&va.date?new Date(va.date+"T00:00:00").toLocaleDateString():"—")+'</span></div><div class="summaryRow"><span>'+t("due")+'</span><span>'+dueReminders().length+'</span></div></div><h2 class="sectionTitle">'+t("upcoming")+'</h2>'+nextActionCard()+'<h2 class="sectionTitle">Timeline</h2>'+todayTimeline()+'<h2 class="sectionTitle">'+t("week")+'</h2>'+weeklySummary()+'<h2 class="sectionTitle">'+t("universe")+'</h2>'+moduleGrid(),"home",true)}
function profileSwitcher(){if(state.profiles.length<2)return"";return '<div class="profileSwitcher">'+state.profiles.map(p=>'<button class="switchChip '+(p.id===state.activeProfileId?'active':'')+'" onclick="setActive(\''+p.id+'\')"><span class="miniA">'+(p.photo?'<img src="'+p.photo+'">':esc(p.avatar||"👶"))+'</span>'+esc(p.name)+'</button>').join("")+'</div>'}
function renderTracking(){root.innerHTML=shell(header(t("daily"),"NAËL")+'<p class="subtitle">'+t("dailyBody")+'</p>'+moduleGrid(),"tracking")}
function renderHealth(){root.innerHTML=shell(header(t("healthTitle"),"NAËL")+'<div class="notice">'+t("healthNotice")+'</div>'+listItem("❤️",t("healthLog"),"","healthlog")+listItem("💉",t("vaccines"),"","vaccines")+listItem("📈",t("growth"),"","growth")+listItem("📅",t("appointments"),"","appointments")+listItem("🗓️",t("calendar"),"","calendar")+listItem("🔔",t("reminders"),"","reminders")+listItem("💊",t("medications"),"","medications")+listItem("🆘",t("emergency"),"","emergency")+listItem("📄",t("documents"),"","documents"),"health")}
function renderDiscover(){root.innerHTML=shell(header(t("discoverTitle"),"NAËL")+'<p class="subtitle">'+t("discoverBody")+'</p>'+listItem("🧸",t("activities"),"","activities")+listItem("⭐",t("milestones"),"","milestones")+listItem("📖",t("journal"),"","journal")+listItem("📷",t("memories"),"","memories")+listItem("✅",t("checklists"),"","checklists")+listItem("🤰",t("pregnancy"),"","pregnancy")+listItem("🧳",t("travel"),"","travel")+listItem("✨",t("naelAI"),t("aiTitle"),"ai"),"discover")}
function listItem(i,a,b,k){return '<div class="list card" onclick="openMod(\''+k+'\')"><div class="li">'+i+'</div><div><h3>'+a+'</h3><p>'+b+'</p></div><div class="right">›</div></div>'}
function renderProfile(){let body=header(t("profiles"),"NAËL")+'<p class="subtitle">'+t("profilesBody")+'</p>';if(state.profiles.length)body+='<h2 class="sectionTitle">'+t("myProfiles")+'</h2>'+state.profiles.map(profileCard).join("");body+='<div style="margin-top:18px">'+btn("+ "+t("createProfile"),"newProfile()")+'</div>';root.innerHTML=shell(body,"profile")}
function profileCard(p){return '<div class="profileCard card">'+avatarHTML(p)+'<div class="meta"><h3>'+esc(p.name)+' '+(p.id===state.activeProfileId?'<span class="badge">'+t("active")+'</span>':'')+'</h3><p>'+esc(ageText(p.birth))+'</p><div class="profileActions">'+(p.id!==state.activeProfileId?btn(t("use"),"setActive(\''+p.id+'\')","secondary mini"):"")+btn(t("edit"),"editProfile(\''+p.id+'\')","secondary mini")+btn(t("delete"),"deleteProfile(\''+p.id+'\')","danger mini")+'</div></div></div>'}
function showProfileForm(){const p=state.editingProfileId?state.profiles.find(x=>x.id===state.editingProfileId):null,d=p||{};state.avatarDraft=p?.avatar||state.avatarDraft||"👶";state.photoDraft=p?.photo||state.photoDraft||null;const icons=["👶","🧸","🐰","🦁","🐼","🦊","🐻","🐯","🌙","⭐","🌈","🩵"];root.innerHTML='<main class="screen">'+header(p?t("editProfile"):t("newProfile"),"NAËL")+'<div class="field"><label>'+t("photoAvatar")+'</label><div style="margin-bottom:12px">'+(state.photoDraft?'<div class="avatar" style="width:78px;height:78px"><img src="'+state.photoDraft+'"></div>':'')+'</div><div class="avatarChoices">'+icons.map(i=>'<button class="avatarPick '+(state.avatarDraft===i&&!state.photoDraft?'active':'')+'" onclick="pickAvatar(\''+i+'\')">'+i+'</button>').join("")+'</div><input type="file" accept="image/*" capture="user" style="margin-top:12px" onchange="loadPhoto(event)"></div>'+field(t("name"),"pname","text",d.name||"")+field(t("birth"),"pbirth","date",d.birth||"")+'<div class="field"><label>'+t("sex")+'</label><select id="psex"><option value="other">'+t("unspecified")+'</option><option value="girl">'+t("girl")+'</option><option value="boy">'+t("boy")+'</option></select></div>'+field(t("birthWeight"),"pweight","number",d.weightBirth||"")+field(t("birthHeight"),"pheight","number",d.heightBirth||"")+'<div class="field"><label>'+t("allergies")+'</label><textarea id="pallergies">'+esc(d.allergies||"")+'</textarea></div>'+field(t("doctor"),"pdoctor","text",d.doctor||"")+btn(p?t("saveChanges"):t("createProfile"),"saveProfileForm()")+'</main>'}
function field(label,id,type,value){return '<div class="field"><label>'+label+'</label><input id="'+id+'" type="'+(type||"text")+'" value="'+esc(value||"")+'"></div>'}
function renderModule(){const k=state.module;if(!activeProfile()&&!["family","settings","ai"].includes(k)){toast(t("createFirst"));state.module=null;state.screen="profile";render();return}if(k==="feeding"){renderFeeding();return}if(k==="sleep"){renderSleep();return}if(k==="diapers"){renderDiapers();return}if(k==="growth"){renderGrowth();return}if(k==="appointments"){renderAppointments();return}if(k==="vaccines"){renderVaccines();return}if(k==="reminders"){renderReminders();return}if(k==="calendar"){renderCalendar();return}if(k==="milestones"){renderMilestones();return}if(k==="ai"){renderAI();return}if(k==="settings"){renderSettings();return}if(k==="medications"){renderMedications();return}if(k==="checklists"){renderChecklists();return}if(k==="emergency"){renderEmergency();return}if(k==="pregnancy"){renderPregnancy();return}if(k==="documents"){renderDocuments();return}if(k==="travel"){renderTravel();return}renderNotes(k)}
function renderNotes(k){root.innerHTML='<main class="screen">'+header(t(mods[k][1]),"NAËL")+'<div class="field"><label>'+t("note")+'</label><textarea id="eventNote"></textarea></div>'+btn(t("add"),"addNoteEvent(\''+k+'\')")+'<h2 class="sectionTitle">'+t("history")+'</h2>'+eventHistory(k)+'</main>'}
function nowLocal(offset){const d=new Date(Date.now()+(offset||0)*60000),z=n=>String(n).padStart(2,"0");return d.getFullYear()+"-"+z(d.getMonth()+1)+"-"+z(d.getDate())+"T"+z(d.getHours())+":"+z(d.getMinutes())}
function renderFeeding(){root.innerHTML='<main class="screen">'+header(t("feeding"),"NAËL")+'<div class="formGrid"><div class="field"><label>'+t("type")+'</label><select id="feedType"><option value="bottle">Biberon</option><option value="breast">Allaitement</option><option value="solid">Solides</option><option value="other">Autre</option></select></div><div class="field"><label>'+t("time")+'</label><input id="feedTime" type="datetime-local" value="'+nowLocal()+'"></div><div class="field"><label>'+t("quantity")+'</label><input id="feedMl" type="number" min="0"></div><div class="field"><label>'+t("duration")+'</label><input id="feedDur" type="number" min="0"></div></div>'+field(t("note"),"feedNote","text","")+btn(t("add"),"addFeeding()")+'<h2 class="sectionTitle">'+t("history")+'</h2>'+eventHistory("feeding")+'</main>'}
function renderSleep(){root.innerHTML='<main class="screen">'+header(t("sleep"),"NAËL")+'<div class="formGrid">'+field(t("start"),"sleepStart","datetime-local",nowLocal(-60))+field(t("end"),"sleepEnd","datetime-local",nowLocal())+'</div>'+field(t("note"),"sleepNote","text","")+btn(t("add"),"addSleep()")+'<h2 class="sectionTitle">'+t("history")+'</h2>'+eventHistory("sleep")+'</main>'}
function renderDiapers(){root.innerHTML='<main class="screen">'+header(t("diapers"),"NAËL")+'<div class="field"><label>'+t("type")+'</label><select id="diaperType"><option value="wet">Pipi</option><option value="dirty">Caca</option><option value="mixed">Mixte</option><option value="dry">Sèche</option></select></div>'+field(t("time"),"diaperTime","datetime-local",nowLocal())+field(t("note"),"diaperNote","text","")+btn(t("add"),"addDiaper()")+'<h2 class="sectionTitle">'+t("history")+'</h2>'+eventHistory("diapers")+'</main>'}
function renderGrowth(){root.innerHTML='<main class="screen">'+header(t("growth"),"NAËL")+'<div class="formGrid">'+field(t("weight"),"gweight","number","")+field(t("height"),"gheight","number","")+'</div>'+btn(t("addMeasure"),"addGrowth()")+'<h2 class="sectionTitle">'+t("charts")+'</h2>'+growthCharts()+'<h2 class="sectionTitle">'+t("history")+'</h2>'+growthHistory()+'</main>'}
function renderAppointments(){const a=state.editingAppointmentId?state.appointments.find(x=>x.id===state.editingAppointmentId):null;root.innerHTML='<main class="screen">'+header(t("appointments"),"NAËL")+(a?'<div class="editBanner">'+t("edit")+'</div>':'')+field(t("subject"),"atitle","text",a?.title||"")+field(t("dateTime"),"adate","datetime-local",a?.date||"")+'<div class="field"><label>'+t("reminder")+'</label><select id="aremind"><option value="0">0 min</option><option value="120">2 h</option><option value="1440" selected>24 h</option><option value="2880">48 h</option></select></div><div class="field"><label>'+t("notes")+'</label><textarea id="anote">'+esc(a?.note||"")+'</textarea></div>'+btn(a?t("saveChanges"):t("add"),a?"saveAppointmentEdit()":"addAppointment()")+'<h2 class="sectionTitle">'+t("upcoming")+'</h2>'+appointmentHistory()+'</main>'}
function renderVaccines(){const v=state.editingVaccineId?state.vaccines.find(x=>x.id===state.editingVaccineId):null;root.innerHTML='<main class="screen">'+header(t("vaccines"),"NAËL")+'<div class="notice">'+t("healthNotice")+'</div>'+field(t("vaccines"),"vname","text",v?.name||"")+field(t("plannedDate"),"vdate","date",v?.date||"")+'<div class="field"><label>'+t("status")+'</label><select id="vstatus"><option value="todo">'+t("todo")+'</option><option value="done">'+t("done")+'</option><option value="postponed">'+t("postponed")+'</option></select></div>'+btn(v?t("saveChanges"):t("add"),v?"saveVaccineEdit()":"addVaccine()")+'<h2 class="sectionTitle">'+t("calendar")+'</h2>'+vaccineHistory()+'</main>'}
function renderReminders(){const r=state.editingReminderId?state.reminders.find(x=>x.id===state.editingReminderId):null;root.innerHTML='<main class="screen">'+header(t("reminders"),"NAËL")+field(t("subject"),"rtitle","text",r?.title||"")+field(t("dateTime"),"rwhen","datetime-local",r?toInput(r.when):"")+btn(r?t("saveChanges"):t("createReminder"),r?"saveReminderEdit()":"addReminder()")+' <button class="btn secondary" onclick="enableNotifications()">'+t("allowNotif")+'</button><h2 class="sectionTitle">'+t("myReminders")+'</h2>'+reminderHistory()+'</main>'}
function renderMilestones(){root.innerHTML='<main class="screen">'+header(t("milestones"),"NAËL")+field(t("moment"),"mtitle","text","")+field(t("date"),"mdate","date","")+btn(t("add"),"addMilestone()")+'<h2 class="sectionTitle">'+t("milestonesList")+'</h2>'+milestoneHistory()+'</main>'}

function renderMedications(){const items=state.medications.filter(x=>x.profileId===state.activeProfileId);root.innerHTML='<main class="screen">'+header(t("medications"),"NAËL")+'<div class="notice">'+t("prescribedOnly")+'</div>'+field(t("medName"),"medName","text","")+field(t("dose"),"medDose","text","")+field(t("schedule"),"medWhen","text","")+btn(t("add"),"addMedication()")+'<h2 class="sectionTitle">'+t("history")+'</h2>'+(items.length?items.map(x=>'<div class="list card"><div class="li">💊</div><div><h3>'+esc(x.name)+'</h3><p>'+esc(x.dose)+' • '+esc(x.schedule)+'</p></div><button class="back" onclick="deleteMedication(\''+x.id+'\')">'+t("delete")+'</button></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>')+'</main>'}
function renderChecklists(){const items=state.checklists.filter(x=>x.profileId===state.activeProfileId);root.innerHTML='<main class="screen">'+header(t("checklists"),"NAËL")+field(t("task"),"taskTitle","text","")+btn(t("add"),"addChecklist()")+'<h2 class="sectionTitle">'+t("checklists")+'</h2>'+(items.length?items.map(x=>'<div class="list card"><div class="li">'+(x.done?"✅":"⬜")+'</div><div><h3>'+esc(x.title)+'</h3></div><div class="inlineActions">'+btn(t("completed"),"toggleChecklist(\''+x.id+'\')","secondary mini")+btn(t("delete"),"deleteChecklist(\''+x.id+'\')","danger mini")+'</div></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>')+'</main>'}
function renderEmergency(){const items=state.emergencyContacts||[];root.innerHTML='<main class="screen">'+header(t("emergency"),"NAËL")+field(t("contactName"),"ecName","text","")+field(t("phone"),"ecPhone","tel","")+field(t("relationship"),"ecRel","text","")+btn(t("add"),"addEmergency()")+'<h2 class="sectionTitle">'+t("emergency")+'</h2>'+(items.length?items.map(x=>'<div class="list card"><div class="li">🆘</div><div><h3>'+esc(x.name)+'</h3><p>'+esc(x.relationship)+' • '+esc(x.phone)+'</p></div><a class="btn success mini" href="tel:'+esc(x.phone)+'">☎</a><button class="back" onclick="deleteEmergency(\''+x.id+'\')">'+t("delete")+'</button></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>')+'</main>'}
function pregnancyWeek(){if(!state.pregnancy.enabled||!state.pregnancy.dueDate)return null;const due=new Date(state.pregnancy.dueDate+"T12:00:00"),start=new Date(due.getTime()-280*86400000),week=Math.floor((Date.now()-start.getTime())/604800000)+1;return Math.max(1,Math.min(42,week))}
function renderPregnancy(){const p=state.pregnancy||base.pregnancy,w=pregnancyWeek();root.innerHTML='<main class="screen">'+header(t("pregnancyTracking"),"NAËL")+'<div class="pregnancyHero card"><div class="pregnancyMoon">☾</div><div><small>'+t("pregnancyTracking")+'</small><b>'+(w?esc(w)+" "+t("weeks"):"—")+'</b></div></div><div class="field"><label>'+t("togglePregnancy")+'</label><select id="pregEnabled"><option value="yes" '+(p.enabled?"selected":"")+'>Oui</option><option value="no" '+(!p.enabled?"selected":"")+'>Non</option></select></div>'+field(t("dueDate"),"pregDue","date",p.dueDate||"")+'<div class="field"><label>'+t("pregnancyNotes")+'</label><textarea id="pregNotes">'+esc(p.notes||"")+'</textarea></div>'+btn(t("saveChanges"),"savePregnancy()")+'</main>'}


function renderDocuments(){const items=state.documents.filter(x=>x.profileId===state.activeProfileId);root.innerHTML='<main class="screen">'+header(t("documents"),"NAËL")+field(t("documentName"),"docName","text","")+'<div class="field"><label>'+t("documentType")+'</label><select id="docType"><option>Carnet de santé</option><option>Ordonnance</option><option>Compte-rendu</option><option>Analyse</option><option>Autre</option></select></div>'+field(t("documentNote"),"docNote","text","")+btn(t("add"),"addDocument()")+'<h2 class="sectionTitle">'+t("documents")+'</h2>'+(items.length?items.map(x=>'<div class="list card"><div class="li">📄</div><div><h3>'+esc(x.name)+'</h3><p>'+esc(x.type)+(x.note?' • '+esc(x.note):'')+'</p></div><button class="back" onclick="deleteDocument(\''+x.id+'\')">'+t("delete")+'</button></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>')+'</main>'}
function renderTravel(){const v=state.travel||base.travel;root.innerHTML='<main class="screen">'+header(t("travelMode"),"NAËL")+'<div class="travelHero card"><div class="travelIcon">🧳</div><div><small>'+t("travelMode")+'</small><b>'+esc(v.destination||"—")+'</b></div></div><div class="field"><label>'+t("enableTravel")+'</label><select id="travelEnabled"><option value="yes" '+(v.enabled?"selected":"")+'>Oui</option><option value="no" '+(!v.enabled?"selected":"")+'>Non</option></select></div>'+field(t("destination"),"travelDest","text",v.destination||"")+'<div class="formGrid">'+field(t("startDate"),"travelStart","date",v.startDate||"")+field(t("endDate"),"travelEnd","date",v.endDate||"")+'</div><div class="field"><label>'+t("travelNotes")+'</label><textarea id="travelNotes">'+esc(v.notes||"")+'</textarea></div>'+btn(t("saveChanges"),"saveTravel()")+'<h2 class="sectionTitle">'+t("checklists")+'</h2><div class="notice">Passe par Check-lists pour préparer couches, vêtements, médicaments, documents et essentiels de voyage.</div></main>'}

function renderSettings(){root.innerHTML='<main class="screen settingsScreen">'+header(t("settings"),"NAËL SETTINGS")+'<h2 class="sectionTitle">'+t("language")+'</h2><div class="langGrid"><button class="langCard '+(state.lang==="fr"?"active":"")+'" onclick="setLanguage(\'fr\')"><span>🇫🇷</span><b>Français</b><small>FR</small></button><button class="langCard '+(state.lang==="en"?"active":"")+'" onclick="setLanguage(\'en\')"><span>🇬🇧</span><b>English</b><small>EN</small></button><button class="langCard '+(state.lang==="ar"?"active":"")+'" onclick="setLanguage(\'ar\')"><span>🇲🇦</span><b>العربية</b><small>AR</small></button><button class="langCard '+(state.lang==="es"?"active":"")+'" onclick="setLanguage(\'es\')"><span>🇪🇸</span><b>Español</b><small>ES</small></button></div><h2 class="sectionTitle">'+t("week")+'</h2>'+weeklySummary()+'<h2 class="sectionTitle">'+t("naelAI")+'</h2><div class="notice">'+t("aiIntro")+'</div><div style="height:10px"></div>'+btn(t("naelAI"),"openMod(\'ai\')","secondary")+'<h2 class="sectionTitle">'+t("backup")+'</h2><div class="rowBtns">'+btn(t("export"),"exportData()","secondary")+btn(t("import"),"triggerImport()","secondary")+'</div><h2 class="sectionTitle">'+t("application")+'</h2>'+btn(t("install"),"installPWA()","secondary")+'<div style="height:10px"></div>'+btn(t("reset"),"resetAll()","danger")+'</main>'+nav("settings")}
function renderAI(){const msgs=state.aiMessages||[];root.innerHTML='<main class="screen">'+header(t("naelAI"),"AI")+'<div class="notice">'+t("aiIntro")+'</div><div class="aiChat card">'+(msgs.length?msgs.map(m=>'<div class="aiMsg '+m.role+'"><b>'+(m.role==="user"?t("you"):"Naël AI")+'</b><p>'+esc(m.text)+'</p></div>').join(""):'<div class="empty">'+t("ask")+'</div>')+'</div><div class="field"><label>'+t("ask")+'</label><textarea id="aiq"></textarea></div>'+btn(t("send"),"askAI()")+'<div style="height:8px"></div>'+btn(t("clearChat"),"clearAI()","secondary")+'</main>'}
function matchesSearch(obj){const q=(state.search||"").trim().toLowerCase();if(!q)return true;return JSON.stringify(obj).toLowerCase().includes(q)}
function searchBox(){return '<div class="searchBox"><span>⌕</span><input placeholder="'+t("search")+'" value="'+esc(state.search||"")+'" oninput="setSearch(this.value)"></div>'}
function eventHistory(k){const a=state.events.filter(e=>e.profileId===state.activeProfileId&&e.type===k&&matchesSearch(e)).slice().reverse();return searchBox()+(a.length?a.map(e=>'<div class="list card"><div style="flex:1"><div class="eyebrow">'+new Date(e.ts).toLocaleString()+'</div><p>'+esc(e.note||k)+'</p>'+(e.ml?'<div class="eventMeta">'+e.ml+' ml</div>':'')+(e.durationMin?'<div class="eventMeta">'+e.durationMin+' min</div>':'')+'</div><button class="back" onclick="deleteEvent(\''+e.id+'\')">'+t("delete")+'</button></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>')}
function growthHistory(){const a=state.growth.filter(x=>x.profileId===state.activeProfileId).slice().reverse();return a.length?a.map(g=>'<div class="list card"><div class="li">📈</div><div><h3>'+esc(g.weight||"—")+' kg • '+esc(g.height||"—")+' cm</h3><p>'+new Date(g.ts).toLocaleDateString()+'</p></div></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>'}
function growthCharts(){const arr=state.growth.filter(g=>g.profileId===state.activeProfileId).slice(-12);return chart(arr,"weight","kg")+chart(arr,"height","cm")}
function chart(arr,key,unit){const vals=arr.map(x=>Number(x[key])).filter(Number.isFinite);if(vals.length<2)return '<div class="notice">'+t("noHistory")+'</div>';const min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,w=320,h=150,p=22;let pts=[];arr.forEach((a,i)=>{const v=Number(a[key]);if(!Number.isFinite(v))return;pts.push([p+i*(w-2*p)/Math.max(1,arr.length-1),h-p-(v-min)*(h-2*p)/span])});return '<div class="card" style="padding:14px;margin:10px 0"><b>'+t(key==="weight"?"weight":"height")+'</b><div class="chart"><svg viewBox="0 0 '+w+' '+h+'"><polyline class="chartLine" points="'+pts.map(x=>x.join(",")).join(" ")+'"/>'+pts.map(x=>'<circle class="chartPoint" cx="'+x[0]+'" cy="'+x[1]+'" r="4"/>').join("")+'</svg></div></div>'}
function appointmentHistory(){const a=state.appointments.filter(x=>x.profileId===state.activeProfileId).sort((x,y)=>new Date(x.date)-new Date(y.date));return a.length?a.map(x=>'<div class="list card"><div class="li">📅</div><div><h3>'+esc(x.title)+'</h3><p>'+new Date(x.date).toLocaleString()+'</p><div class="inlineActions">'+btn(t("edit"),"editAppointment(\''+x.id+'\')","secondary mini")+btn(t("delete"),"deleteAppointment(\''+x.id+'\')","danger mini")+'</div></div></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>'}
function vaccineHistory(){const a=state.vaccines.filter(x=>x.profileId===state.activeProfileId);return a.length?a.map(v=>'<div class="list card"><div class="li">💉</div><div><h3>'+esc(v.name)+'</h3><p>'+esc(v.date||"—")+' • '+esc(v.status)+'</p><div class="inlineActions">'+btn(t("edit"),"editVaccine(\''+v.id+'\')","secondary mini")+btn(t("done"),"markVaccineDone(\''+v.id+'\')","success mini")+btn(t("delete"),"deleteVaccine(\''+v.id+'\')","danger mini")+'</div></div></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>'}
function reminderHistory(){const a=state.reminders.filter(x=>x.profileId===state.activeProfileId).sort((x,y)=>new Date(x.when)-new Date(y.when));return a.length?a.map(r=>'<div class="list card"><div class="li">'+(r.done?"✅":"🔔")+'</div><div><h3>'+esc(r.title)+'</h3><p>'+new Date(r.when).toLocaleString()+'</p><div class="inlineActions">'+btn(t("edit"),"editReminder(\''+r.id+'\')","secondary mini")+btn(t("done"),"toggleReminder(\''+r.id+'\')","secondary mini")+btn(t("delete"),"deleteReminder(\''+r.id+'\')","danger mini")+'</div></div></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>'}
function milestoneHistory(){const a=state.milestones.filter(x=>x.profileId===state.activeProfileId).slice().reverse();return a.length?a.map(m=>'<div class="list card"><div class="li">⭐</div><div><h3>'+esc(m.title)+'</h3><p>'+esc(m.date||"—")+'</p></div></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>'}
function weeklySummary(){const pid=state.activeProfileId;if(!pid)return '<div class="empty card">'+t("createFirst")+'</div>';const since=Date.now()-7*86400000,ev=state.events.filter(e=>e.profileId===pid&&new Date(e.ts).getTime()>=since),mins=ev.filter(e=>e.type==="sleep").reduce((n,e)=>n+(Number(e.durationMin)||0),0);return '<div class="weekGrid"><div class="metric card"><b>'+ev.filter(e=>e.type==="feeding").length+'</b><small>'+t("feeding")+'</small></div><div class="metric card"><b>'+ev.filter(e=>e.type==="diapers").length+'</b><small>'+t("diapers")+'</small></div><div class="metric card"><b>'+Math.round(mins/60)+' h</b><small>'+t("sleep")+'</small></div><div class="metric card"><b>'+state.growth.filter(g=>g.profileId===pid&&new Date(g.ts).getTime()>=since).length+'</b><small>'+t("growth")+'</small></div></div>'}
function renderCalendar(){if(!state.calendarCursor)state.calendarCursor=new Date().toISOString().slice(0,7);const [y,m]=state.calendarCursor.split("-").map(Number),first=new Date(y,m-1,1),start=(first.getDay()+6)%7,days=new Date(y,m,0).getDate(),prev=new Date(y,m-1,0).getDate();let cells="";for(let i=0;i<42;i++){let d=i-start+1,cy=y,cm=m,other=false;if(d<1){d=prev+d;cm=m-1;if(cm<1){cm=12;cy--}other=true}else if(d>days){d-=days;cm=m+1;if(cm>12){cm=1;cy++}other=true}const key=cy+"-"+String(cm).padStart(2,"0")+"-"+String(d).padStart(2,"0"),dots=calendarItems(key);cells+='<div class="day '+(other?"other ":"")+(key===new Date().toISOString().slice(0,10)?"today ":"")+(key===state.calendarSelected?"selected":"")+'" onclick="selectCalendarDay(\''+key+'\')"><b>'+d+'</b><div class="dots">'+dots.map(x=>'<i class="dot '+x+'"></i>').join("")+'</div></div>'}root.innerHTML='<main class="screen">'+header(t("calendar"),"NAËL")+'<div class="calendarHead">'+btn("‹","moveCalendar(-1)","secondary mini")+'<b>'+first.toLocaleDateString(state.lang,{month:"long",year:"numeric"})+'</b>'+btn("›","moveCalendar(1)","secondary mini")+'</div><div class="calendarGrid">'+["L","M","M","J","V","S","D"].map(x=>'<div class="dow">'+x+'</div>').join("")+cells+'</div>'+(state.calendarSelected?calendarDayList(state.calendarSelected):"")+'</main>'}
function calendarItems(key){const pid=state.activeProfileId,o=[];state.appointments.filter(a=>a.profileId===pid&&a.date.slice(0,10)===key).forEach(()=>o.push(""));state.vaccines.filter(v=>v.profileId===pid&&v.date===key).forEach(()=>o.push("v"));state.reminders.filter(r=>r.profileId===pid&&r.when.slice(0,10)===key&&!r.done).forEach(()=>o.push("r"));return o.slice(0,5)}
function calendarDayList(key){const pid=state.activeProfileId,items=[];state.appointments.filter(a=>a.profileId===pid&&a.date.slice(0,10)===key).forEach(a=>items.push(["📅",a.title]));state.vaccines.filter(v=>v.profileId===pid&&v.date===key).forEach(v=>items.push(["💉",v.name]));state.reminders.filter(r=>r.profileId===pid&&r.when.slice(0,10)===key&&!r.done).forEach(r=>items.push(["🔔",r.title]));return '<h2 class="sectionTitle">'+key+'</h2>'+(items.length?items.map(i=>'<div class="list card"><div class="li">'+i[0]+'</div><div><h3>'+esc(i[1])+'</h3></div></div>').join(""):'<div class="empty card">'+t("noHistory")+'</div>')}
function toInput(v){if(!v)return"";const d=new Date(v),z=n=>String(n).padStart(2,"0");return d.getFullYear()+"-"+z(d.getMonth()+1)+"-"+z(d.getDate())+"T"+z(d.getHours())+":"+z(d.getMinutes())}
window.go=s=>{if(s==="settings"){state.module="settings";save();history.pushState({},'',location.pathname);render();return}state.screen=s;state.module=null;save();history.pushState({},'',location.pathname);render()}
window.openMod=k=>{state.module=k;save();history.pushState({},'',location.pathname);render()}
window.back=()=>{if(state.module){state.module=null;save();render();return}if(state.screen!=="home"){state.screen="home";save();render()}}
window.newProfile=()=>{state.editingProfileId=null;state.avatarDraft="👶";state.photoDraft=null;showProfileForm()}
window.editProfile=id=>{state.editingProfileId=id;showProfileForm()}
window.pickAvatar=i=>{state.avatarDraft=i;state.photoDraft=null;showProfileForm()}
window.loadPhoto=e=>{const f=e.target.files&&e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.photoDraft=r.result;showProfileForm()};r.readAsDataURL(f)}
window.saveProfileForm=()=>{const name=document.getElementById("pname").value.trim();if(!name){toast(t("name"));return}const data={name,birth:document.getElementById("pbirth").value,sex:document.getElementById("psex").value,weightBirth:document.getElementById("pweight").value,heightBirth:document.getElementById("pheight").value,allergies:document.getElementById("pallergies").value,doctor:document.getElementById("pdoctor").value,avatar:state.avatarDraft||"👶",photo:state.photoDraft||null};if(state.editingProfileId)Object.assign(state.profiles.find(x=>x.id===state.editingProfileId),data);else{const p={id:uid(),...data};state.profiles.push(p);state.activeProfileId=p.id}state.editingProfileId=null;save();state.screen="profile";render()}
window.deleteProfile=id=>{if(!confirm(t("delete")+" ?"))return;state.profiles=state.profiles.filter(x=>x.id!==id);["events","appointments","vaccines","growth","milestones","reminders","medications","checklists","documents"].forEach(k=>state[k]=state[k].filter(x=>x.profileId!==id));if(state.activeProfileId===id)state.activeProfileId=state.profiles[0]?.id||null;save();render()}
window.setActive=id=>{state.activeProfileId=id;save();render()}
window.addNoteEvent=k=>{const note=document.getElementById("eventNote").value.trim();if(!note)return;state.events.push({id:uid(),profileId:state.activeProfileId,type:k,note,ts:new Date().toISOString()});save();renderModule()}
window.addFeeding=()=>{const ts=document.getElementById("feedTime").value;state.events.push({id:uid(),profileId:state.activeProfileId,type:"feeding",feedType:document.getElementById("feedType").value,ml:Number(document.getElementById("feedMl").value)||null,durationMin:Number(document.getElementById("feedDur").value)||null,note:document.getElementById("feedNote").value,ts:new Date(ts).toISOString()});save();renderModule()}
window.addSleep=()=>{const a=document.getElementById("sleepStart").value,b=document.getElementById("sleepEnd").value,d=Math.round((new Date(b)-new Date(a))/60000);if(!a||!b||d<=0){toast(t("sleep"));return}state.events.push({id:uid(),profileId:state.activeProfileId,type:"sleep",durationMin:d,note:document.getElementById("sleepNote").value,ts:new Date(b).toISOString()});save();renderModule()}
window.addDiaper=()=>{const ts=document.getElementById("diaperTime").value;state.events.push({id:uid(),profileId:state.activeProfileId,type:"diapers",diaperType:document.getElementById("diaperType").value,note:document.getElementById("diaperNote").value,ts:new Date(ts).toISOString()});save();renderModule()}
window.deleteEvent=id=>{state.events=state.events.filter(e=>e.id!==id);save();renderModule()}
window.addGrowth=()=>{state.growth.push({id:uid(),profileId:state.activeProfileId,weight:document.getElementById("gweight").value,height:document.getElementById("gheight").value,ts:new Date().toISOString()});save();renderModule()}
window.addAppointment=()=>{const title=document.getElementById("atitle").value,date=document.getElementById("adate").value,id=uid();if(!title||!date)return;state.appointments.push({id,profileId:state.activeProfileId,title,date,note:document.getElementById("anote").value});const mins=Number(document.getElementById("aremind").value);state.reminders.push({id:uid(),profileId:state.activeProfileId,title:t("appointments")+": "+title,when:new Date(new Date(date).getTime()-mins*60000).toISOString(),done:false,sourceId:id});save();renderModule()}
window.editAppointment=id=>{state.editingAppointmentId=id;renderModule()}
window.saveAppointmentEdit=()=>{const a=state.appointments.find(x=>x.id===state.editingAppointmentId);if(!a)return;a.title=document.getElementById("atitle").value;a.date=document.getElementById("adate").value;a.note=document.getElementById("anote").value;state.editingAppointmentId=null;save();renderModule()}
window.deleteAppointment=id=>{state.appointments=state.appointments.filter(x=>x.id!==id);state.reminders=state.reminders.filter(x=>x.sourceId!==id);save();renderModule()}
window.addVaccine=()=>{const name=document.getElementById("vname").value,date=document.getElementById("vdate").value,id=uid();if(!name)return;state.vaccines.push({id,profileId:state.activeProfileId,name,date,status:document.getElementById("vstatus").value});if(date)state.reminders.push({id:uid(),profileId:state.activeProfileId,title:t("vaccines")+": "+name,when:new Date(date+"T09:00:00").toISOString(),done:false,sourceId:id});save();renderModule()}
window.editVaccine=id=>{state.editingVaccineId=id;renderModule()}
window.saveVaccineEdit=()=>{const v=state.vaccines.find(x=>x.id===state.editingVaccineId);if(!v)return;v.name=document.getElementById("vname").value;v.date=document.getElementById("vdate").value;v.status=document.getElementById("vstatus").value;state.editingVaccineId=null;save();renderModule()}
window.markVaccineDone=id=>{const v=state.vaccines.find(x=>x.id===id);if(v)v.status="done";save();renderModule()}
window.deleteVaccine=id=>{state.vaccines=state.vaccines.filter(x=>x.id!==id);state.reminders=state.reminders.filter(x=>x.sourceId!==id);save();renderModule()}
window.addReminder=()=>{const title=document.getElementById("rtitle").value,when=document.getElementById("rwhen").value;if(!title||!when)return;state.reminders.push({id:uid(),profileId:state.activeProfileId,title,when:new Date(when).toISOString(),done:false});save();renderModule()}
window.editReminder=id=>{state.editingReminderId=id;renderModule()}
window.saveReminderEdit=()=>{const r=state.reminders.find(x=>x.id===state.editingReminderId);if(!r)return;r.title=document.getElementById("rtitle").value;r.when=new Date(document.getElementById("rwhen").value).toISOString();state.editingReminderId=null;save();renderModule()}
window.toggleReminder=id=>{const r=state.reminders.find(x=>x.id===id);if(r)r.done=!r.done;save();renderModule()}
window.deleteReminder=id=>{state.reminders=state.reminders.filter(x=>x.id!==id);save();renderModule()}
window.addMilestone=()=>{const title=document.getElementById("mtitle").value;if(!title)return;state.milestones.push({id:uid(),profileId:state.activeProfileId,title,date:document.getElementById("mdate").value});save();renderModule()}
window.moveCalendar=d=>{let [y,m]=(state.calendarCursor||new Date().toISOString().slice(0,7)).split("-").map(Number);m+=d;if(m<1){m=12;y--}if(m>12){m=1;y++}state.calendarCursor=y+"-"+String(m).padStart(2,"0");state.calendarSelected=null;save();renderCalendar()}
window.selectCalendarDay=k=>{state.calendarSelected=k;save();renderCalendar()}
window.setLanguage=l=>{state.lang=l;save();render()}
window.enableNotifications=async()=>{if(!("Notification"in window))return;await Notification.requestPermission()}
window.askAI=async()=>{const q=(document.getElementById("aiq").value||"").trim();if(!q)return;state.aiMessages.push({role:"user",text:q});save();renderAI();try{const p=activeProfile(),r=await fetch("/api/ai",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:q,language:state.lang,context:{child:p,events:state.events.filter(e=>!p||e.profileId===p.id).slice(-30),growth:state.growth.filter(g=>!p||g.profileId===p.id).slice(-12),appointments:state.appointments.filter(a=>!p||a.profileId===p.id).slice(-12),vaccines:state.vaccines.filter(v=>!p||v.profileId===p.id).slice(-12),reminders:state.reminders.filter(x=>!p||x.profileId===p.id).slice(-12)}})}),d=await r.json();state.aiMessages.push({role:"assistant",text:d.answer||d.error||"Naël AI indisponible."})}catch(e){state.aiMessages.push({role:"assistant",text:"Naël AI indisponible."})}save();renderAI()}
window.clearAI=()=>{state.aiMessages=[];save();renderAI()}

window.addMedication=()=>{const name=document.getElementById("medName").value.trim();if(!name)return;state.medications.push({id:uid(),profileId:state.activeProfileId,name,dose:document.getElementById("medDose").value,schedule:document.getElementById("medWhen").value});save();renderModule()}
window.deleteMedication=id=>{state.medications=state.medications.filter(x=>x.id!==id);save();renderModule()}
window.addChecklist=()=>{const title=document.getElementById("taskTitle").value.trim();if(!title)return;state.checklists.push({id:uid(),profileId:state.activeProfileId,title,done:false});save();renderModule()}
window.toggleChecklist=id=>{const x=state.checklists.find(x=>x.id===id);if(x)x.done=!x.done;save();renderModule()}
window.deleteChecklist=id=>{state.checklists=state.checklists.filter(x=>x.id!==id);save();renderModule()}
window.addEmergency=()=>{const name=document.getElementById("ecName").value.trim(),phone=document.getElementById("ecPhone").value.trim();if(!name||!phone)return;state.emergencyContacts.push({id:uid(),name,phone,relationship:document.getElementById("ecRel").value});save();renderModule()}
window.deleteEmergency=id=>{state.emergencyContacts=state.emergencyContacts.filter(x=>x.id!==id);save();renderModule()}
window.savePregnancy=()=>{state.pregnancy={enabled:document.getElementById("pregEnabled").value==="yes",dueDate:document.getElementById("pregDue").value,notes:document.getElementById("pregNotes").value};save();renderModule()}


window.addDocument=()=>{const name=document.getElementById("docName").value.trim();if(!name)return;state.documents.push({id:uid(),profileId:state.activeProfileId,name,type:document.getElementById("docType").value,note:document.getElementById("docNote").value});save();renderModule()}
window.deleteDocument=id=>{state.documents=state.documents.filter(x=>x.id!==id);save();renderModule()}
window.saveTravel=()=>{state.travel={enabled:document.getElementById("travelEnabled").value==="yes",destination:document.getElementById("travelDest").value,startDate:document.getElementById("travelStart").value,endDate:document.getElementById("travelEnd").value,notes:document.getElementById("travelNotes").value};save();renderModule()}
window.setSearch=q=>{state.search=q;save()}

window.exportData=()=>{const b=new Blob([JSON.stringify(state,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="nael-backup.json";a.click()}
window.triggerImport=()=>document.getElementById("importFile").click()
document.getElementById("importFile").addEventListener("change",e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state=Object.assign({},base,JSON.parse(r.result));save();render()}catch(err){toast("Invalid file")}};r.readAsText(f)})
let deferredPrompt=null;addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferredPrompt=e})
window.installPWA=async()=>{if(deferredPrompt){deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null}else toast("Add to Home Screen")}
window.resetAll=()=>{if(confirm(t("reset")+" ?")){localStorage.removeItem(KEY);state=JSON.parse(JSON.stringify(base));render()}}
function checkDueNotifications(){if(!("Notification" in window)||Notification.permission!=="granted")return;const now=Date.now();let changed=false;state.reminders.forEach(r=>{if(r.done||r.notified||r.profileId!==state.activeProfileId)return;const ts=new Date(r.when).getTime();if(ts<=now&&now-ts<3600000){try{new Notification("Naël",{body:r.title,icon:"/icon.svg"})}catch(e){}r.notified=true;changed=true}});if(changed)save()}
setInterval(checkDueNotifications,30000);
checkDueNotifications();
addEventListener("popstate",()=>window.back());
render();
